(()=>{let queued=false;const plus='<path d="M12 5v14M5 12h14"/>',documentIcon='<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h8"/>';
function normalize(){document.querySelectorAll('.view>.panel>.head').forEach(head=>{const title=head.querySelector('h2');if(!title)return;let tools=head.querySelector(':scope>.shortcut-actions');if(!tools){tools=document.createElement('div');tools.className='shortcut-actions';head.append(tools)}let icon=head.querySelector('.sector-icon,.config-inherit-icon');if(icon&&icon.parentElement!==head)head.prepend(icon);if(!icon){icon=document.createElement('span');icon.className='sector-icon config-inherit-icon header-origin-icon';icon.setAttribute('aria-hidden','true');const view=head.closest('.view');const path=typeof icons!=='undefined'?(icons[view?.id]||icons.records||icons.settings):documentIcon;icon.innerHTML='<svg viewBox="0 0 24 24">'+path+'</svg>';head.prepend(icon)}for(const button of [...head.querySelectorAll(':scope>button')]){const label=button.getAttribute('aria-label')||button.title||button.textContent.trim();button.title=label;button.setAttribute('aria-label',label);button.classList.remove('btn');button.classList.add('shortcut-circle');button.style.setProperty('border-radius','50%','important');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(/^(?:\+|Novo|Nova|Adicionar)/i.test(label)?plus:documentIcon)+'</svg>';tools.append(button)}const identity=[...head.children].find(el=>el!==tools&&el.contains(title));if(identity){identity.classList.add('header-identity');identity.style.minWidth='0'}head.dataset.headerStandard='yes';title.title=title.textContent})}
window.addEventListener('DOMContentLoaded',()=>{normalize();new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;normalize()})}).observe(document.body,{childList:true,subtree:true})});})();
(()=>{window.addEventListener('DOMContentLoaded',()=>{const content=document.querySelector('#salary-view .content');if(!content||document.getElementById('salary-search'))return;const toolbar=document.createElement('div');toolbar.className='jobs-toolbar';const input=document.createElement('input');input.type='search';input.id='salary-search';input.placeholder='Buscar cargo';input.setAttribute('aria-label','Buscar cargo nos salários');const filter=()=>{const query=input.value.trim().toLocaleLowerCase('pt-BR');document.querySelectorAll('#salary-list .salary-row').forEach(row=>row.hidden=!!query&&!row.querySelector('.salary-job-identity')?.textContent.toLocaleLowerCase('pt-BR').includes(query))};input.oninput=filter;toolbar.append(input);content.prepend(toolbar);new MutationObserver(filter).observe(document.getElementById('salary-list'),{childList:true});})})();
